/** The first line break, captured. */
export declare const CAPTURED_LINE_BREAK: RegExp;
/** The colon a declaration's `raws.between` opens with, with the whitespace around it. */
export declare const COLON_AND_WHITESPACE: RegExp;
/** A hex color anywhere. */
export declare const CONTAINS_HEX_COLOR: RegExp;
/** A Windows break alone; narrow since `max-empty-lines` and `indentation` ask about the pair. */
