/** Every quotation mark, either kind. */
export declare const EVERY_QUOTATION_MARK: RegExp;
/** A character {@link EVERY_KEPT_LINE_MASK} matches. */
export declare const KEPT_LINE_MASK: RegExp;
/** A byte order mark opening a text, which PostCSS prints back in front of a root whose input carried one. */
export declare const LEADING_BYTE_ORDER_MARK: RegExp;
/** Every parenthesis, either kind. */
export declare const EVERY_PARENTHESIS: RegExp;
/** Every character but a line feed, the one character PostCSS counts a line by: a carriage return, bare or opening a Windows pair, matches with the rest. */
export declare const EVERY_CHARACTER_BUT_A_LINE_FEED: RegExp;
/** A line feed, the one character PostCSS counts a line by. */
export declare const LINE_FEED: RegExp;
/** Every run of breaks as PostCSS reads them, a Windows pair and a line feed alike, nothing between them: what `max-empty-lines` collapses, whichever way each break is spelled. */
