/** Every semicolon. */
export declare const EVERY_SEMICOLON: RegExp;
/** Every space. */
export declare const EVERY_SPACE: RegExp;
/** Every tab. */
export declare const EVERY_TAB: RegExp;
/** Every whitespace character. */
export declare const EVERY_WHITESPACE: RegExp;
/** A browser extension's `__MSG_…__`. */
