/** A fraction opening on its point. */
export declare const FRACTION_WITHOUT_LEADING_ZERO: RegExp;
/** A fraction behind zeros, the zeros captured apart. */
export declare const FRACTION_WITH_LEADING_ZEROS: RegExp;
/** A fraction ending in zeros, the kept digits captured apart. */
export declare const FRACTION_WITH_TRAILING_ZEROS: RegExp;
/** A leading hex color. */
export declare const HEX_COLOR: RegExp;
/** The one whitespace character closing a hexadecimal escape; a Windows pair counts as one. */
export declare const HEX_ESCAPE_TERMINATOR: RegExp;
