/** An ASCII letter a text ends in, behind which `style-search` opens a call's arguments at a `(`. */
export declare const ENDS_WITH_ASCII_LETTER: RegExp;
/** An escape a text ends in, behind an even run of backslashes: a backslash and one character that is no hexadecimal digit and no line break, or up to six hexadecimal digits with the one whitespace character closing them, a Windows pair counting as one. */
export declare const ENDS_WITH_ESCAPE: RegExp;
/** `import`, any case. */
export declare const IMPORT_AT_RULE: RegExp;
/** A break closing a `//` comment where a form feed is the comment's text, which is Less's reading: a line feed or a carriage return, bare or in front of one. Wider than {@link LINE_BREAK}, since Less rewrites a bare carriage return to a line feed before parsing and Sass reads one as a newline; narrower than {@link INLINE_COMMENT_BREAK_OR_FORM_FEED}, which is Sass's. The reading of a syntax that has said nothing, since it is the one standing here before the syntaxes were told apart. */
export declare const INLINE_COMMENT_BREAK: RegExp;
/** A break closing a `//` comment where a form feed closes one too, which is Sass's reading: `postcss-scss` tokenizes a line in the character and dart-sass compiles the code behind it. Spelled as {@link CSS_LINE_BREAK} is, which asks another question of the same three characters. */
export declare const INLINE_COMMENT_BREAK_OR_FORM_FEED: RegExp;
/** The character a preprocessor's interpolation opens with in front of its `{`: Sass's `#` and Less's `@`. Spelled as {@link NAME_CHARACTER_BESIDE_IDENTIFIER} is, which asks another question of the same two characters. The third spelling of {@link EVERY_INTERPOLATION}, postcss-simple-vars' `$(…)`, closes on a parenthesis and carries no brace to ask about, and a template's braces ({@link TPL_INTERPOLATION}) are left out here as they are there: no engine reads a call behind `${p}url(`, and `@csstools/css-tokenizer` reads the address. */
export declare const INTERPOLATION_MARK: RegExp;
/** The last line as PostCSS counts lines, its break excluded, a bare carriage return being a character of the line; nothing where the text ends in a break. */
export declare const LAST_LINE: RegExp;
/** A leading block comment, breaks aside, its content captured. */
export declare const LEADING_BLOCK_COMMENT: RegExp;
/** A leading `}`, whitespace short of a break aside, as {@link LEADING_INDENT_AND_CONTENT} reads a line's indentation. */
export declare const LEADING_CLOSING_BRACE: RegExp;
/** A leading `)`, whitespace short of a break aside, as {@link LEADING_INDENT_AND_CONTENT} reads a line's indentation. */
export declare const LEADING_CLOSING_PARENTHESIS: RegExp;
/** A leading colon and the tokenizer whitespace behind it. */
export declare const LEADING_COLON_AND_WHITESPACE: RegExp;
